/**
 * Ibn Amer — Runtime Augmentation Service Worker
 * Task 20: PWA Offline Quran Caching
 *
 * This script is loaded by the main sw.js via importScripts() — but since
 * the main sw.js is auto-generated by next-pwa/Workbox and we can't edit it
 * directly, we instead register our own routes here by importing this file
 * from a small wrapper sw.
 *
 * Strategy overview:
 * ─────────────────────────────────────────────────────────────────────────
 * | Resource                  | Strategy              | Max age  | Limit  |
 * |───────────────────────────|───────────────────────|──────────|────────|
 * | /fonts/p*.ttf (Quran)     | CacheFirst            | 1 year   | 620    |
 * | /quran.json               | StaleWhileRevalidate  | 30 days  | 1      |
 * | /layout.json              | StaleWhileRevalidate  | 30 days  | 1      |
 * | /quran-*-metadata.json    | StaleWhileRevalidate  | 7 days   | 10     |
 * | /Recitation-*.json        | CacheFirst            | 30 days  | 4      |
 * | Firebase audio CDN (mp3)  | CacheFirst+Range      | 7 days   | 200    |
 * | /offline.html             | Precached fallback    | forever  | 1      |
 * ─────────────────────────────────────────────────────────────────────────
 *
 * NOTE: quran.json (7.8 MB) is NOT precached — it is cached lazily on first
 * request. This prevents the initial install from blocking on a huge file.
 */

const CACHE_VERSION = 'ibn-amer-v2';
const OFFLINE_PAGE = '/offline.html';

// ── Install: precache the offline fallback page ───────────────────────────
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(`${CACHE_VERSION}-offline`).then((cache) => {
      return cache.add(new Request(OFFLINE_PAGE, { cache: 'reload' }));
    })
  );
});

// ── Single unified fetch handler ──────────────────────────────────────────
// Handles: offline fallback → Quran fonts → Quran data → recitation → audio
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // 1. Navigation fallback: if offline, serve /offline.html
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() =>
        caches.open(`${CACHE_VERSION}-offline`)
          .then((cache) => cache.match(OFFLINE_PAGE))
          .then((resp) => resp || new Response('Offline', { status: 503 }))
      )
    );
    return;
  }

  // 2. Quran page fonts: p1.ttf … p604.ttf + SurahHeader.ttf
  // CacheFirst — fonts never change, must work offline
  if (url.pathname.startsWith('/fonts/') && url.pathname.endsWith('.ttf')) {
    event.respondWith(
      caches.open(`${CACHE_VERSION}-quran-fonts`).then(async (cache) => {
        const cached = await cache.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) cache.put(request, response.clone());
        return response;
      })
    );
    return;
  }

  // 3. Large Quran data JSON: StaleWhileRevalidate
  const isQuranJson =
    url.pathname === '/quran.json' ||
    url.pathname === '/layout.json' ||
    url.pathname === '/layout1.json' ||
    url.pathname.match(/^\/quran-.*-metadata\.json$/);

  if (isQuranJson) {
    event.respondWith(
      caches.open(`${CACHE_VERSION}-quran-data`).then(async (cache) => {
        const cached = await cache.match(request);
        const fetchPromise = fetch(request).then((response) => {
          if (response.ok) cache.put(request, response.clone());
          return response;
        });
        return cached || fetchPromise;
      })
    );
    return;
  }

  // 4. Recitation audio-timing JSON: CacheFirst
  if (url.pathname.match(/^\/Recitation-.*\.json$/)) {
    event.respondWith(
      caches.open(`${CACHE_VERSION}-recitation-data`).then(async (cache) => {
        const cached = await cache.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) cache.put(request, response.clone());
        return response;
      })
    );
    return;
  }

  // 5. Quran audio MP3 from CDN: passthrough (too large to cache)
  if (url.hostname !== self.location.hostname && url.pathname.endsWith('.mp3')) {
    // Let the browser handle range requests natively
    return;
  }
});



// ── Cache size management ─────────────────────────────────────────────────
// Trim font cache to 620 entries (604 pages + headers + extras)
self.addEventListener('message', (event) => {
  if (event.data?.type === 'TRIM_CACHE') {
    trimCache(`${CACHE_VERSION}-quran-fonts`, 620);
    trimCache(`${CACHE_VERSION}-quran-data`, 10);
    trimCache(`${CACHE_VERSION}-recitation-data`, 5);
  }
});

async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length > maxEntries) {
    // Delete oldest entries
    const toDelete = keys.slice(0, keys.length - maxEntries);
    await Promise.all(toDelete.map((key) => cache.delete(key)));
  }
}
